// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import { config as loadEnv } from "dotenv";
import { defineConfig } from "prisma/config";

// Next.js reads `.env.local` on its own, but the Prisma CLI does not — plain
// `dotenv/config` loads `.env` only. Listing both keeps one source of truth:
// `.env.local` wins, `.env` is a fallback. First file to define a key wins.
loadEnv({ path: [".env.local", ".env"], quiet: true });

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: process.env["DATABASE_URL"],
    // `prisma migrate dev` needs a second, throwaway database to detect drift.
    // `npx prisma dev` provides one; hosted Postgres usually does not, in which
    // case leave this unset and Prisma creates a temporary one itself.
    shadowDatabaseUrl: process.env["SHADOW_DATABASE_URL"],
  },
});
